function validate([dungeon]) {
  if (!Array.isArray(dungeon) || dungeon.length < 1 || dungeon.length > 200) return 'dungeon needs 1 to 200 rows.';
  const cols = Array.isArray(dungeon[0]) ? dungeon[0].length : 0;
  if (cols < 1 || cols > 200) return 'Each row needs 1 to 200 cells.';
  for (const row of dungeon) {
    if (!Array.isArray(row) || row.length !== cols) return 'All rows must have the same length.';
    if (row.some(v => !Number.isInteger(v) || v < -1000 || v > 1000)) return 'Each cell is an integer between -1000 and 1000.';
  }
  return null;
}

