function calculateMinimumHP(dungeon) {
  const m = dungeon.length, n = dungeon[0].length;
  // Can the knight survive when starting with health h? Track the most health he can have in each cell.
  function survives(h) {
    const most = Array.from({ length: m }, () => new Array(n).fill(-Infinity));
    for (let r = 0; r < m; r++) {
      for (let c = 0; c < n; c++) {
        let before = r === 0 && c === 0 ? h : Math.max(r > 0 ? most[r - 1][c] : -Infinity, c > 0 ? most[r][c - 1] : -Infinity);
        if (before <= 0) continue;
        const after = before + dungeon[r][c];
        if (after > 0) most[r][c] = after;
      }
    }
    return most[m - 1][n - 1] > 0;
  }
  let lo = 1, hi = 1000 * (m + n) + 1;
  while (lo < hi) {
    const mid = Math.floor((lo + hi) / 2);
    if (survives(mid)) hi = mid; else lo = mid + 1;
  }
  return lo;
}

