function generate(rand, size) {
  const m = size === 'large' ? 40 + Math.floor(rand() * 61) : 1 + Math.floor(rand() * 5);
  const n = size === 'large' ? 40 + Math.floor(rand() * 61) : 1 + Math.floor(rand() * 5);
  const span = size === 'large' ? 1000 : 12;
  // Lean towards damage so that the answer is usually more than 1.
  const harm = 0.5 + rand() * 0.3;
  return [Array.from({ length: m }, () => Array.from({ length: n }, () => {
    const v = Math.floor(rand() * (span + 1));
    return rand() < harm ? -v : v;
  }))];
}
